const NS='http://schemas.openxmlformats.org/wordprocessingml/2006/main';
const children=(n,name)=>Array.from(n.children).filter(x=>x.localName===name);
const all=(n,name)=>Array.from(n.getElementsByTagNameNS(NS,name));
const attr=(n,k,v)=>n.setAttributeNS(NS,`w:${k}`,v);
function node(doc,name,attrs={}){let n=doc.createElementNS(NS,`w:${name}`);for(let [k,v] of Object.entries(attrs))attr(n,k,v);return n;}
function setText(cell,value){let ts=all(cell,'t');if(!ts.length){let p=node(cell.ownerDocument,'p'),r=node(cell.ownerDocument,'r'),t=node(cell.ownerDocument,'t');r.append(t);p.append(r);cell.append(p);ts=[t];}ts[0].textContent=value;ts.slice(1).forEach(n=>n.textContent='');}
function mergeLabel(row,label,span,continuation=false){const cells=children(row,'tc'),target=cells[1],doc=row.ownerDocument,pr=children(target,'tcPr')[0];children(pr,'gridSpan').forEach(n=>n.remove());pr.append(node(doc,'gridSpan',{val:span}));let widths=cells.slice(1,1+span).reduce((s,c)=>s+(+children(children(c,'tcPr')[0],'tcW')[0]?.getAttributeNS(NS,'w')||0),0);let width=children(pr,'tcW')[0];if(width)attr(width,'w',widths);if(continuation!==null)pr.append(node(doc,'vMerge',continuation?{}:{val:'restart'}));setText(target,label);if(span===4){for(const n of all(target,'sz'))attr(n,'val','18');for(const n of all(target,'spacing'))attr(n,'line','240');}cells.slice(2,1+span).forEach(n=>n.remove());}
export async function generateDocx(state,type,month){const response=await fetch(new URL(`../templates/${type}.docx?v=cda1b9438026`,import.meta.url));if(!response.ok)throw Error('The form could not be opened. Reload the page and try again.');const zip=await JSZip.loadAsync(await response.arrayBuffer()),xml=new DOMParser().parseFromString(await zip.file('word/document.xml').async('string'),'application/xml');if(xml.querySelector('parsererror'))throw Error('The form could not be read.');for(const size of all(xml,'pgSz')){attr(size,'w',PAPER.wordWidth);attr(size,'h',PAPER.wordHeight);size.removeAttributeNS(NS,'code');size.removeAttributeNS(NS,'orient');}const rows=buildMonth(state,type,month),setup=state.setups[type],p=state.profile;const date=new Date(`${month}-01T12:00:00Z`),title=date.toLocaleDateString('en-US',{month:'long',year:'numeric',timeZone:'UTC'});const totals=rows.reduce((a,r)=>{for(const [k,v]of Object.entries(r.totals))a[k]=(a[k]||0)+v;return a;},{});
const values={NAME:p.name.toUpperCase(),SIGNATURE_NAME:(p.signatureName||p.name).toUpperCase(),DEPARTMENT:p.department.toUpperCase(),DESIGNATION:p.designation,SIGNATORY:setup.signatory.toUpperCase(),MONTH:type==='dtr'?`${date.toLocaleDateString('en-US',{month:'long',timeZone:'UTC'}).toUpperCase()} 1-${daysInMonth(month)}, ${date.getUTCFullYear()}`:title.toUpperCase(),MONTH_TITLE:title,OFFICIAL:setup.official||'____________________',REGULAR:setup.regular||'____________________',SATURDAY:setup.saturday||'____________________',SUNDAY:setup.sunday||'____________________',LEC:(totals.lecture||0).toFixed(1),LAB:(totals.laboratory||0).toFixed(1)};
if(type==='dtr'){
 for(let day=1;day<=31;day++){const r=rows[day-1];values[`D${day}`]=r?`${day}`:'';const am=r?.sessions.find(s=>+s.start.slice(0,2)<12),pm=r?.sessions.find(s=>+s.start.slice(0,2)>=12);[am?timeLabel(am.start):'',am?timeLabel(am.end):'',pm?timeLabel(pm.start):'',pm?timeLabel(pm.end):'',r?.sessions.length?`${r.totals.lecture.toFixed(1)} ${r.totals.laboratory.toFixed(1)}`:''].forEach((v,i)=>values[`D${day}_${i}`]=v);}
 for(const table of all(xml,'tbl').filter(t=>children(t,'tr').length===32)){const trs=children(table,'tr');for(const r of rows)if(r.label)mergeLabel(trs[r.day],r.label,4,null);}
}else{
 const tables=all(xml,'tbl');for(let day=1;day<=31;day++){const r=rows[day-1];values[`DAY${day}`]=r?String(day):'';values[`TOTAL${day}`]=r?.sessions.length?r.total.toFixed(1):'';['class','consultation','related','others'].forEach((cat,ci)=>{let periods=r?.sessions.filter(s=>s.category===cat)||[];for(let slot=0;slot<3;slot++){const s=periods[slot];values[`F${day}_${ci}_${slot}_in`]=s?timeLabel(s.start):'';values[`F${day}_${ci}_${slot}_out`]=s?timeLabel(s.end):'';values[`F${day}_${ci}_${slot}_hours`]=s?duration(s).toFixed(2):'';}});if(r?.change?.kind==='Related activity'){const trs=children(tables[day<=15?0:1],'tr'),index=day<=15?13+(day-1)*3:4+(day-16)*3;const slot=[0,1,2].find(i=>!r.sessions.filter(s=>s.category==='class')[i]&&!r.sessions.filter(s=>s.category==='consultation')[i]);if(slot!==undefined)mergeLabel(trs[index+slot],r.change.description,6,null);else throw Error('The form has no free space for this activity description. Reduce the class or consultation periods for this day.');}if(r?.label){const trs=children(tables[day<=15?0:1],'tr'),index=day<=15?13+(day-1)*3:4+(day-16)*3;for(let i=0;i<3;i++)mergeLabel(trs[index+i],i?'':r.label,12,i>0);if(r.change?.kind==='Official Travel'){const cell=children(trs[index],'tc')[1],paragraph=children(cell,'p')[0].cloneNode(true);setText(paragraph,r.change.reference);cell.append(paragraph);}}}
}
for(const t of all(xml,'t'))t.textContent=t.textContent.replace(/\{\{([^}]+)\}\}/g,(_,key)=>values[key]??'');zip.file('word/document.xml',new XMLSerializer().serializeToString(xml));return zip.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',compression:'DEFLATE'});}
